def mandelbrot_row(py: int, width: int, height: int, max_iter: int) -> list[int]:

    row: list[int] = []
    ci: float = (py / height) * 2.4 - 1.2
    for px in range(width):
        cr: float = (px / width) * 3.0 - 2.2
        zr: float = 0.0
        zi: float = 0.0
